            CountDownLatch sample=new CountDownLatch(1),flush=new CountDownLatch(1);java.util.concurrent.atomic.AtomicReference<float[]> observed=new java.util.concurrent.atomic.AtomicReference<>();Map<Integer,JSONObject> additional=new ConcurrentHashMap<>();SensorEventCallback oracle=new SensorEventCallback(){public void onSensorChanged(SensorEvent e){observed.set(e.values.clone());if(e.values.length>=3&&Math.abs(e.values[0]-12.25f)<0.00001f&&Math.abs(e.values[1]+7.5f)<0.00001f&&Math.abs(e.values[2]-9.125f)<0.00001f)sample.countDown();}public void onFlushCompleted(Sensor s){flush.countDown();}public void onSensorAdditionalInfo(SensorAdditionalInfo frame){try{JSONObject copy=new JSONObject().put("serial",frame.serial);JSONArray integers=new JSONArray(),floats=new JSONArray();if(frame.intValues!=null)for(int n:frame.intValues)integers.put(n);if(frame.floatValues!=null)for(float n:frame.floatValues)floats.put(Double.doubleToRawLongBits((double)n));copy.put("ints",frame.intValues==null?JSONObject.NULL:integers).put("floats",frame.floatValues==null?JSONObject.NULL:floats);additional.put(frame.type,copy);}catch(Exception ignored){}}};
            check(manager.registerListener(oracle,sensor,20000,0,HardwareSensors.events()),"a separate public SDK listener independently opens the actual sensor");
            try{boolean matched=sample.await(3,TimeUnit.SECONDS);check(matched,"the independent SDK listener receives the controlled acceleration within emulator conversion precision; observed="+java.util.Arrays.toString(observed.get()));Object[] queued=live.events.toArray();float[] actual=observed.get();String expectedSource="fn main(){let v=db_list();";for(int i=0;i<3;i++){long bits=Double.doubleToRawLongBits((double)actual[i]);sdkValues.put((double)actual[i]);sdkBits.put(bits);expectedSource+="db_add(v,db_int("+bits+"));";}h.vm(expectedSource+"return state_set(\"sensor-expected\",v)-1;}");phase("sc_sample");check(true,"the actual VM preserves all three independent SDK float-to-double bit patterns exactly, including the observed emulator conversion, and a real SensorEvent timestamp");check(manager.flush(oracle)&&flush.await(3,TimeUnit.SECONDS),"an independent public SDK flush receives its actual onFlushCompleted callback");
                int frames=0,payloads=0;for(Object value:queued){if(!(value instanceof JSONObject))continue;JSONObject e=(JSONObject)value;if(!e.optString("event").equals("additional_info"))continue;JSONObject expected=additional.get(e.getInt("type"));if(expected==null)continue;if(e.getInt("serial")!=expected.getInt("serial"))continue;Object actualInt=e.get("int_values"),actualFloat=e.get("float_values");if(expected.isNull("ints")){if(actualInt!=JSONObject.NULL)throw new IOException("Additional-info null integer mismatch");}else if(!expected.getJSONArray("ints").toString().equals(((JSONArray)actualInt).toString()))throw new IOException("Additional-info integer payload mismatch");if(expected.isNull("floats")){if(actualFloat!=JSONObject.NULL)throw new IOException("Additional-info null float mismatch");}else{JSONArray a=(JSONArray)actualFloat,b=expected.getJSONArray("floats");if(a.length()!=b.length())throw new IOException("Additional-info float length mismatch");for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getLong("$real")!=b.getLong(i))throw new IOException("Additional-info float bits mismatch");}if((actualInt instanceof JSONArray&&((JSONArray)actualInt).length()>0)||(actualFloat instanceof JSONArray&&((JSONArray)actualFloat).length()>0))payloads++;frames++;}additionalFrames=frames;additionalPayloads=payloads;check(frames>0&&payloads>0,"real provider additional-info frames agree with a distinct actual SDK listener, including serials, nullable arrays and exact converted float bits");
            }finally{manager.unregisterListener(oracle);}
            SensorEventCallback oldCallback=live.callback;phase("sc_flush");phase("sc_complete");h.vm("fn main(){let h="+HardwareInputChecks.quote(handle)+";let i=device_info(h);if db_kind(device_field(i,\"flush_pending\"))!=0||db_word(device_field(i,\"last_flush_completed\"))!=db_word(state_get(\"sensor-flush\")){return 1;}if db_word(sensor_configure(h,40000,500000))!=1{return 2;}i=device_info(h);if db_word(device_field(i,\"period_us\"))!=40000||db_word(device_field(i,\"max_report_latency_us\"))!=500000{return 3;}return 0;}");check(true,"actual VM flush completion carries its own request ID and the same live SDK listener can be explicitly reconfigured afterwards");check(live.callback!=oldCallback&&live.configuration==2,"valid reconfiguration replaces the actual Android listener while retaining the workspace handle and a new configuration identity");probe("active",40000,500000);staleCallback(live,oldCallback);
            h.vm("fn main(){let h="+HardwareInputChecks.quote(handle)+";if sensor_configure(h,4999,0)||sensor_configure(h,20000,-1)||sensor_configure(h,20000,60000001)||sensor_flush(h,0)||sensor_flush(h,8001){return 1;}if !device_info(h){return 2;}return 0;}");check(true,"invalid period/latency/deadline requests reject before changing or closing the existing live sensor subscription");
            File foreign=new File(h.root,"foreign");foreign.mkdirs();try{h.vm(foreign,"fn main(){if sensor_flush("+HardwareInputChecks.quote(handle)+",1000)||sensor_configure("+HardwareInputChecks.quote(handle)+",20000,0){return 1;}return 0;}");check(true,"another workspace cannot flush or reconfigure this sensor handle");}finally{VmHardware.closeWorkspace(foreign);}
