            try{if(!blocked.await(2,TimeUnit.SECONDS))throw new IOException("Could not hold the real callback Handler");long start=SystemClock.elapsedRealtime();phase("sc_pending");long end=start+5000;while(!expiring.closed&&SystemClock.elapsedRealtime()<end)Thread.sleep(5);check(expiring.closed&&SystemClock.elapsedRealtime()-start<4500,"the independent wall deadline retires a real pending flush while Android's actual callback Handler remains blocked, without another VM access");probe("idle",0,0);}finally{release.countDown();HardwareSensors.events().post(drained::countDown);if(!drained.await(3,TimeUnit.SECONDS))throw new IOException("Callback Handler did not drain after release");}check(expiring.events.isEmpty(),"late queued SDK callbacks do not revive an expired handle or publish data after close");
            open(id,true);HardwareSensors.Subscription fresh=stream();phase("sc_flush");phase("sc_complete");check(fresh!=expiring&&fresh.lastCompleted==1&&!fresh.closed,"a separately reopened legacy sensor_open uses zero latency and receives its own fresh real flush completion");probe("active",20000,0);
            boolean dynamic=manager.isDynamicSensorDiscoverySupported();h.vm("fn main(){let w=sensor_watch();"+(dynamic?"if !w{return 1;}return device_close(db_word(w))-1;":"if w{return 1;}if !worker_equal(db_word(db_at(device_error(),0)),\"unsupported_operation\"){return 2;}return 0;")+"}");check(true,"dynamic discovery follows the actual SDK support flag without inventing sensor attach/detach events");
            java.lang.reflect.Method save=MainActivity.class.getDeclaredMethod("savePermission",String.class,Object.class);save.setAccessible(true);try{h.ui(()->{try{save.invoke(h.host,"sensors",false);}catch(Exception e){throw new RuntimeException(e);}});check(fresh.closed,"actual UI-thread Collie Sensors denial closes the existing SDK subscription");h.vm("fn main(){if sensor_batch_open("+HardwareInputChecks.quote(id)+",20000,1000000)||sensor_watch(){return 1;}return 0;}");check(true,"the next real VM cannot reopen sensor batching or discovery after Sensors denial");probe("idle",0,0);}finally{h.ui(()->{try{save.invoke(h.host,"sensors",true);}catch(Exception e){throw new RuntimeException(e);}});}
